var numbers = [1, 2, 3, 4, 5];

// forEach - iterate
numbers.forEach(n => console.log(n));

// map - transform
var doubled = numbers.map(n => n * 2); // [2,4,6,8,10]

// filter - select
var evens = numbers.filter(n => n % 2 === 0); // [2,4]

// reduce - aggregate
var sum = numbers.reduce((acc, n) => acc + n, 0); // 15

// find - first match
numbers.find(n => n > 3); // 4

