numbers.some(n => n > 3); // true

// every - all match
numbers.every(n => n > 0); // true

// sort
var sorted = numbers.sort((a, b) => a - b);

// Object literal
var person = {
  name: 'Alice',
  age: 30,
  email: 'alice@example.com',
  address: {
