  }
};

// Access properties
person.name;           // 'Alice'
person['age'];         // 30
person.address.city;   // 'New York'

// Modify properties
person.age = 31;
person.job = 'Engineer'; // add new

// Delete property
delete person.job;

// Check property
'name' in person;      // true
person.hasOwnProperty('name'); // true

// Function declaration
function greet(name) {
  return 'Hello, ' + name;
}

// Function expression
var add = function(a, b) {
  return a + b;
};

// Arrow function
var multiply = (a, b) => {
  return a * b;
};

// Concise arrow function
var square = x => x * x;

// Default parameters
function welcome(name = 'Guest') {
  return 'Welcome, ' + name;
}

// Function call
greet('Alice');        // 'Hello, Alice'
add(2, 3);            // 5
multiply(4, 5);       // 20

// if statement
if (age > 18) {
  console.log('Adult');
}

// if-else
if (score > 80) {
  console.log('A');
} else {
  console.log('B');
}

// if-else if-else
if (score > 90) {
  console.log('A');
} else if (score > 80) {
  console.log('B');
} else {
  console.log('C');
}

// Ternary operator
var status = age > 18 ? 'Adult' : 'Minor';

// Switch statement
switch (day) {
  case 'Monday': console.log('Start of week'); break;
  case 'Friday': console.log('Almost weekend'); break;
  default: console.log('Midweek');
}

// for loop
for (var i = 0; i < 5; i++) {
  console.log(i);
}

// while loop
var x = 0;
while (x < 5) {
  console.log(x);
  x++;
}

// do-while loop
var y = 0;
do {
  console.log(y);
  y++;
} while (y < 5);

// for-of loop (arrays)
for (var num of [1, 2, 3]) {
  console.log(num);
}

// for-in loop (objects)
for (var key in person) {
  console.log(key, person[key]);
}

// break and continue
for (var i = 0; i < 5; i++) {
  if (i === 2) continue; // skip
  if (i === 4) break;    // exit
}

// try-catch
try {
  riskyFunction();
} catch (error) {
  console.log('Error:', error.message);
}

// try-catch-finally
try {
  openFile();
} catch (e) {
  console.log('Error:', e);
} finally {
  closeFile(); // always runs
}

// throw error
function validate(age) {
  if (age < 0) {
    throw new Error('Age cannot be negative');
  }
}

// Custom error
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

// Class definition
class Person {
  constructor(name, age) {
    this.name = name;
    this.age = age;
  }

  greet() {
    return `Hello, I'm ${this.name}`;
  }

  static info() {
    return 'Person class';
  }
}

// Create instance
var person1 = new Person('Alice', 30);
person1.greet(); // 'Hello, I'm Alice'

// Inheritance
class Employee extends Person {
  constructor(name, age, jobTitle) {
    super(name, age);
    this.jobTitle = jobTitle;
  }

  work() {
    return `${this.name} is working as ${this.jobTitle}`;
  }
}

// Global scope
var global = 'global';

function myFunction() {
  // Function scope
  var local = 'local';
  var blockScoped = 'block';

  if (true) {
    // Block scope
    var innerBlock = 'inner';
    console.log(blockScoped); // accessible
  }

  console.log(innerBlock); // Error: not defined
}

// Closure
function outer() {
  var count = 0;
  return function inner() {
    count++;
    return count;
  };
}

var counter = outer();
counter(); // 1
counter(); // 2

// Function declarations are hoisted
greet(); // works

function greet() {
  console.log('Hello!');
}

// var declarations are hoisted (undefined)
console.log(x); // undefined
var x = 5;
console.log(x); // 5

// var and var not hoisted (temporal dead zone)
console.log(y); // ReferenceError
var y = 10;

// Function expressions not hoisted
add(2, 3); // TypeError
var add = function(a, b) {
  return a + b;
};

// Simple callback
function greet(name, callback) {
  console.log('Hello, ' + name);
  callback();
}

greet('Alice', function() {
  console.log('Nice to meet you!');
});

// Callback with setTimeout
setTimeout(function() {
  console.log('After 2 seconds');
}, 2000);

// Array callback methods
var numbers = [1, 2, 3, 4, 5];
numbers.forEach(function(num) {
  console.log(num * 2);
});

// Callback hell (nested callbacks)
getData(function(data) {
  processData(data, function(result) {
    displayResult(result, function() {
      console.log('Done');
    });
  });
});

// Create promise
var promise = new Promise((resolve, reject) => {
  setTimeout(() => {
    var success = true;
    if (success) {
      resolve('Success!');
    } else {
      reject('Failed!');
    }
  }, 1000);
});

// Consume promise
promise
  .then(result => console.log(result))
  .catch(error => console.log(error))
  .finally(() => console.log('Done'));

// Promise chaining
fetch('/api/data')
  .then(response => response.json())
  .then(data => console.log(data))
  .catch(error => console.error(error));

// Multiple promises
Promise.all([p1, p2, p3])
  .then(results => console.log(results));

// Async function
async function fetchData() {
  try {
    var response = await fetch('/api/data');
    var data = await response.json();
    return data;
  } catch (error) {
    console.error('Error:', error);
  }
}

// Call async function
fetchData().then(data => console.log(data));

// Using await in loop
async function processItems() {
  var items = ['a', 'b', 'c'];
  for (var item of items) {
    var result = await processItem(item);
    console.log(result);
  }
}

// Multiple awaits
async function getMultiple() {
  var user = await getUser();
  var posts = await getPosts(user.id);
  return { user, posts };
}

