// Arrow function basics
var add = (a, b) => {
  return a + b;
};

// Concise body (implicit return)
var multiply = (a, b) => a * b;

// Single parameter (omit parentheses)
var square = x => x * x;

// No parameters
var random = () => Math.random();

// Multi-line body
var process = (x) => {
  var doubled = x * 2;
  return doubled + 1;
};

// Lexical 'this'
var person = {
  name: 'Alice',
  greet: function() {
    var arrow = () => {
      console.log(this.name); // 'Alice'
    };
    arrow();
  }
};

// Array destructuring
var [a, b, c] = [1, 2, 3];
var [first, ...rest] = [1, 2, 3, 4];

// Object destructuring
var { name, age } = { name: 'Alice', age: 30 };
var { name: fullName } = { name: 'Alice' };

// Nested destructuring
var { address: { city } } = {
  address: { city: 'NYC', zip: '10001' }
};

// Default values
var { status = 'active' } = {};

// Function parameter destructuring
function display({ name, age }) {
  console.log(name, age);
}

display({ name: 'Alice', age: 30 });

// Rest operator
var [head, ...tail] = [1, 2, 3, 4];
// head = 1, tail = [2, 3, 4]

// Spread array
var arr1 = [1, 2, 3];
var arr2 = [...arr1, 4, 5];
// arr2 = [1, 2, 3, 4, 5]

// Spread object
var obj1 = { a: 1, b: 2 };
var obj2 = { ...obj1, c: 3 };
// obj2 = { a: 1, b: 2, c: 3 }

// Combine arrays
var combined = [...arr1, ...arr2];

// Function arguments
var numbers = [2, 3, 1];
Math.max(...numbers); // 3

// Copy array
var copy = [...arr1]; // shallow copy

// Copy object
var objCopy = { ...obj1 };

// Merge objects
var merged = { ...obj1, ...obj2, c: 4 };

// Rest parameters
function sum(...numbers) {
  return numbers.reduce((a, b) => a + b, 0);
}

sum(1, 2, 3, 4); // 10

// Mix regular and rest params
function greet(greeting, ...names) {
  names.forEach(name => {
    console.log(greeting + ', ' + name);
  });
}

greet('Hello', 'Alice', 'Bob', 'Charlie');

// Rest in destructuring
var [head, ...tail] = [1, 2, 3, 4, 5];

// Rest in object destructuring
var { a, b, ...rest } = { a: 1, b: 2, c: 3, d: 4 };
// rest = { c: 3, d: 4 }

var numbers = [1, 2, 3, 4, 5];

// Filter - select items
var evens = numbers.filter(n => n % 2 === 0);
// [2, 4]

// Map - transform items
var doubled = numbers.map(n => n * 2);
// [2, 4, 6, 8, 10]

// Reduce - aggregate
var sum = numbers.reduce((acc, n) => acc + n, 0);
// 15

// Chaining
var result = numbers
  .filter(n => n > 2)
  .map(n => n * 2)
  .reduce((a, b) => a + b);
// (3 + 4 + 5) * 2 = 24

// Complex reduce
var grouped = items.reduce((acc, item) => {
  acc[item.category] = acc[item.category] || [];
  acc[item.category].push(item);
  return acc;
}, {});

// Object to JSON string
var person = { name: 'Alice', age: 30 };
var json = JSON.stringify(person);
// '{"name":"Alice","age":30}'

// JSON string to object
var jsonStr = '{"name":"Bob","age":25}';
var obj = JSON.parse(jsonStr);

// Stringify options
JSON.stringify(person, null, 2); // pretty print
JSON.stringify(person, ['name']); // only name property

// Parse with reviver
var dateJson = '{"date":"2024-01-15"}';
var withDate = JSON.parse(dateJson, (key, value) => {
  if (key === 'date') return new Date(value);
  return value;
});

// Arrays in JSON
var arr = [1, 2, { id: 1, name: 'item' }];
var jsonArr = JSON.stringify(arr);

// GET request
fetch('/api/users')
  .then(response => response.json())
  .then(data => console.log(data))
  .catch(error => console.error(error));

// POST request
fetch('/api/users', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({ name: 'Alice', age: 30 })
})
  .then(response => response.json())
  .then(data => console.log(data));

// With async/await
async function getUsers() {
  var response = await fetch('/api/users');
  var data = await response.json();
  return data;
}

// Check response status
fetch('/api/data')
  .then(response => {
    if (!response.ok) throw new Error('Network error');
    return response.json();
  });

// Store data
localStorage.setItem('username', 'Alice');
localStorage.setItem('user', JSON.stringify({ id: 1, name: 'Alice' }));

// Retrieve data
var username = localStorage.getItem('username');
var user = JSON.parse(localStorage.getItem('user'));

// Check if key exists
if (localStorage.getItem('token')) {
  console.log('User is logged in');
}

// Remove item
localStorage.removeItem('username');

// Clear all
localStorage.clear();

// Get all keys
for (var i = 0; i < localStorage.length; i++) {
  var key = localStorage.key(i);
  console.log(key, localStorage.getItem(key));
}

// Listen for storage changes
window.addEventListener('storage', (e) => {
  console.log(`${e.key} changed to ${e.newValue}`);
});

// Create regex
var pattern = /hello/i;  // case-insensitive
var pattern2 = new RegExp('hello', 'i');

// Test if matches
/email/.test('my@email.com');     // true

// Find matches
'hello world hello'.match(/hello/g); // ['hello', 'hello']

// Replace
'hello world'.replace(/world/, 'JavaScript');

// Common patterns
/^[a-z]+$/;           // lowercase letters only
/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i; // email
/^\d{3}-\d{3}-\d{4}$/; // phone: 123-456-7890

// Character classes
/[abc]/;      // a, b, or c
/[a-z]/;      // a-z
/\d/;        // digit
/\w/;        // word char
/\s/;        // whitespace

// Quantifiers
/a+/;         // one or more
/a*/;         // zero or more
